package com.voicex.pro;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.media.*;import android.net.Uri;import android.provider.Settings;import android.widget.*;import java.io.File;
public class MainActivity extends Activity {
 LinearLayout root; MediaRecorder recorder; MediaPlayer player; File clip; TextView status; boolean recording;
 static GradientDrawable bg(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(20);return d;}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 public void onCreate(Bundle b){super.onCreate(b);clip=new File(getCacheDir(),"test.m4a");show(false);}
 void text(String s,int z){TextView t=new TextView(this);t.setTextColor(-1);t.setTextSize(z);t.setText(s);t.setPadding(0,dp(10),0,dp(10));root.addView(t);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(-1);b.setBackground(bg(0xff513589));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.bottomMargin=dp(8);root.addView(b,p);b.setOnClickListener(v->r.run());}
 void show(boolean settings){finishRecord();releasePlayer();ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(32),dp(24),dp(24));root.setBackgroundColor(0xff050508);getWindow().setStatusBarColor(0xff050508);getWindow().setNavigationBarColor(0xff050508);scroll.addView(root);setContentView(scroll);text("VOICE X / PRO",30);text("OFFLINE AUDIO LAB • PROTOTYPE",12);button(settings?"HOME":"SETTINGS",()->show(!settings));if(settings){text("Voice profiles • local preview",18);text("Experimental pitch",14);TextView pitchValue=new TextView(this);pitchValue.setTextColor(0xffa8e6ed);pitchValue.setText("Pitch +"+getSharedPreferences("voice",0).getInt("pitch",25)+"%");root.addView(pitchValue);SeekBar s=new SeekBar(this);s.setMax(60);s.setContentDescription("Pitch adjustment");s.setProgress(getSharedPreferences("voice",0).getInt("pitch",25));root.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int x,boolean u){getSharedPreferences("voice",0).edit().putInt("pitch",x).apply();pitchValue.setText("Pitch +"+x+"%");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});for(String p:new String[]{"Original","Soft pitch","Bright pitch"})button(p,()->{getSharedPreferences("voice",0).edit().putInt("pitch",p.equals("Original")?0:p.equals("Soft pitch")?18:32).apply();show(true);});text("Playback speed",16);SeekBar speed=new SeekBar(this);speed.setMax(50);speed.setProgress(getSharedPreferences("voice",0).getInt("speed",25));root.addView(speed);speed.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int x,boolean u){getSharedPreferences("voice",0).edit().putInt("speed",x).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});text("Preview volume",16);SeekBar volume=new SeekBar(this);volume.setMax(100);volume.setProgress(getSharedPreferences("voice",0).getInt("volume",80));root.addView(volume);volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int x,boolean u){getSharedPreferences("voice",0).edit().putInt("volume",x).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});button("Reset audio settings",()->{getSharedPreferences("voice",0).edit().putInt("pitch",25).putInt("volume",80).putInt("speed",25).apply();show(true);});button("Delete recording",()->{releasePlayer();if(clip.exists()&&!clip.delete())Toast.makeText(this,"Could not delete recording",Toast.LENGTH_SHORT).show();else Toast.makeText(this,"Recording deleted",Toast.LENGTH_SHORT).show();});button("Overlay permission",()->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))));text("Pitch demo only. No AI model or game microphone routing.",14);return;}
 status=new TextView(this);status.setTextColor(0xffc5a5ff);status.setText("Voice test ready");root.addView(status);button("Record / stop",this::record);button("Play adjusted",()->play(1f+getSharedPreferences("voice",0).getInt("pitch",25)/100f,false));button("Play original",()->play(1f,true));button("Stop playback",()->{releasePlayer();status.setText("Playback stopped");});button("Launch Free Fire + panel",this::launch);button("Stop panel",()->stopService(new Intent(this,EdgeService.class)));button("Device compatibility",()->new AlertDialog.Builder(this).setTitle("Compatibility").setMessage("Android API "+Build.VERSION.SDK_INT+"\nMicrophone permission: "+(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==0?"Granted":"Not granted")+"\nOverlay permission: "+(Settings.canDrawOverlays(this)?"Granted":"Not granted")+"\nLive game microphone: Not supported by this build").setPositiveButton("OK",null).show());text("Game microphone remains unchanged.",14);}
 void releasePlayer(){if(player!=null){player.release();player=null;}}
 void record(){if(recording){finishRecord();return;}if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=0){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},1);return;}try{releasePlayer();recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioChannels(1);recorder.setAudioSamplingRate(44100);recorder.setAudioEncodingBitRate(96000);recorder.setMaxDuration(60000);recorder.setOnInfoListener((r,w,e)->{if(r==recorder&&w==MediaRecorder.MEDIA_RECORDER_INFO_MAX_DURATION_REACHED)finishRecord();});recorder.setOutputFile(clip.getAbsolutePath());recorder.prepare();recorder.start();recording=true;status.setText("Recording");}catch(Exception e){if(recorder!=null)recorder.release();recorder=null;status.setText("Recording failed");}}
 void finishRecord(){if(!recording)return;try{recorder.stop();status.setText("Recording saved");}catch(Exception e){clip.delete();}finally{recorder.release();recorder=null;recording=false;}}
 void play(float p,boolean original){if(recording||!clip.exists()){status.setText(recording?"Stop recording first":"Record a voice sample first");return;}try{releasePlayer();player=new MediaPlayer();player.setDataSource(clip.getAbsolutePath());player.prepare();float volumeLevel=getSharedPreferences("voice",0).getInt("volume",80)/100f;player.setVolume(volumeLevel,volumeLevel);player.setPlaybackParams(new PlaybackParams().setSpeed(original?1f:0.75f+getSharedPreferences("voice",0).getInt("speed",25)/100f).setPitch(p));player.setOnCompletionListener(m->{if(m==player){releasePlayer();status.setText("Playback finished");}});player.start();status.setText("Playing test");}catch(Exception e){releasePlayer();status.setText("Playback failed");}}
 void launch(){finishRecord();releasePlayer();if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));return;}Intent game=getPackageManager().getLaunchIntentForPackage("com.dts.freefireth");if(game==null)game=getPackageManager().getLaunchIntentForPackage("com.dts.freefiremax");if(game==null){status.setText("Free Fire not found");return;}try{startForegroundService(new Intent(this,EdgeService.class));startActivity(game);}catch(RuntimeException e){stopService(new Intent(this,EdgeService.class));status.setText("Could not launch game or overlay");}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==1&&results.length>0&&results[0]==0&&!recording&&status!=null)record();else if(request==1&&status!=null)status.setText("Microphone permission denied");}
 protected void onStop(){finishRecord();releasePlayer();super.onStop();}
}
